INSERT INTO permissions (name, description) VALUES ('plugin_devicelog_access', 'Имеет доступ к журналам устройств');
INSERT INTO userRolePermissions (roleId, permissionId)
SELECT id, currval('permissions_id_seq') FROM userroles WHERE name IN ('Администратор', 'Супер-Администратор');

DELETE FROM userRolePermissions WHERE roleId=1 AND permissionId=(SELECT id FROM permissions WHERE name='plugin_devicelog_access');
INSERT INTO userRolePermissions VALUES (1, (SELECT id FROM permissions WHERE name='plugin_devicelog_access'));
DELETE FROM userRolePermissions WHERE roleId=2 AND permissionId=(SELECT id FROM permissions WHERE name='plugin_devicelog_access');
INSERT INTO userRolePermissions VALUES (2, (SELECT id FROM permissions WHERE name='plugin_devicelog_access'));

CREATE TABLE plugin_devicelog_settings (
    id serial NOT NULL CONSTRAINT plugin_devicelog_settings_pr_key PRIMARY KEY,
    customerId INT NOT NULL REFERENCES customers( id ) ON DELETE CASCADE,
    logsPreservePeriod INT NOT NULL DEFAULT 30
);

CREATE TABLE plugin_devicelog_setting_rule_devices (
    ruleId INT NOT NULL REFERENCES plugin_devicelog_settings_rules( id ) ON DELETE CASCADE,
    deviceId INT NOT NULL REFERENCES devices( id ) ON DELETE CASCADE
);
